export default function Toolbar({ mode, onModeChange, colors, selectedColor, onSelectColor }) {
  return (
    <div className="pointer-events-auto absolute left-4 top-4 flex items-center gap-1 rounded-lg border border-white/10 bg-black/60 p-1.5 backdrop-blur-sm">
      {MODES.map((m) => (
        <button
          key={m.id}
          type="button"
          aria-label={m.label}
          title={m.label}
          onClick={() => onModeChange(m.id)}
          className={`flex h-8 w-8 items-center justify-center rounded-md transition-colors ${
            mode === m.id ? "bg-white/15 text-white" : "text-white/60 hover:bg-white/10 hover:text-white"
          }`}
        >
          <ModeIcon mode={m}/>
        </button>
      ))}

      {mode === "select-material" && (
        <>
          <div className="mx-1 h-5 w-px bg-white/15" />
          {colors.map((color, i) => {
            const colorIndex = i;

            return (
              <button
                key={colorIndex}
                type="button"
                aria-label={`Paint color ${colorIndex}`}
                onClick={() => onSelectColor(colorIndex)}
                className={`h-6 w-6 rounded-md border-2 transition-transform ${
                  selectedColor === colorIndex ? "scale-110 border-white" : "border-transparent"
                }`}
                style={{ backgroundColor: color }}
              />
            );
          })}
        </>
      )}
    </div>
  );
}

function ModeIcon({ mode }) {
  const id = mode.id
  const iconPath = mode.icon

  if (id === "pan") {
    return (
      <svg viewBox="3 3 20 20" className="h-4 w-4" fill="transparent" stroke="white" strokeWidth="2">
        {/* <path d="M12 2v20M2 12h20" strokeLinecap="round" /> */}
        <path d={iconPath} strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }
  if (id === "place-ant") {
    return (
      <svg viewBox="0 0 512 512" className="h-4 w-4" fill="white" stroke="white" strokeWidth="10">
        {/* <circle cx="12" cy="12" r="5" /> */}
        <path d={iconPath} />
      </svg>
    );
  }
  if (id === "place-spawner") {
    return (
      <svg viewBox="0 0 24 24" className="h-4 w-4" fill="transparent" stroke="white" strokeWidth="2">
        <circle cx="12" cy="12" r="10" />
      </svg>
    );
  }

  if (id === "select-material") {
    return (
      <svg viewBox="0 0 24 24" className="h-4 w-4" fill="transparent" stroke="white" strokeWidth="2">
        <path d={iconPath} />
      </svg>
    );
  }

  // Draw any other icon using this:
  return (
    <svg viewBox="0 0 32 28" className="h-4 w-4" fill="white" stroke="white" strokeWidth="1">
      {/* <path d="M3 21l3-3m0 0l9-9 3 3-9 9H6z" strokeLinecap="round" strokeLinejoin="round" /> */}
      <path d={iconPath} />
    </svg>
  );
}
